package com.productionhouse.crm.mediahouse.postproduction.api;
import com.productionhouse.crm.mediahouse.postproduction.dto.*;import com.productionhouse.crm.mediahouse.postproduction.service.PostProductionTaskService;import jakarta.validation.Valid;import org.springframework.data.domain.Page;import org.springframework.http.HttpStatus;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.time.LocalDate;
@RestController @RequestMapping("/api/mediahouse/postproduction") public class PostProductionTaskController{private final PostProductionTaskService service;public PostProductionTaskController(PostProductionTaskService service){this.service=service;}
@GetMapping @PreAuthorize("hasAuthority('POSTPRODUCTION_READ')") public Page<PostProductionTaskResponse> list(@RequestParam(required=false)String q,@RequestParam(required=false)String status,@RequestParam(required=false)String projectRef,@RequestParam(required=false)Long assigneeId,@RequestParam(required=false)LocalDate dueBefore,@RequestParam(required=false)LocalDate dueAfter,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size,@RequestParam(defaultValue="createdAt")String sort,@RequestParam(defaultValue="desc")String direction){return service.list(q,status,projectRef,assigneeId,dueBefore,dueAfter,page,size,sort,direction);}
@GetMapping("/{id}") @PreAuthorize("hasAuthority('POSTPRODUCTION_READ')") public PostProductionTaskResponse get(@PathVariable Long id){return service.get(id);}
@PostMapping @ResponseStatus(HttpStatus.CREATED) @PreAuthorize("hasAuthority('POSTPRODUCTION_WRITE')") public PostProductionTaskResponse create(@Valid @RequestBody PostProductionTaskRequest request){return service.create(request);}
@PutMapping("/{id}") @PreAuthorize("hasAuthority('POSTPRODUCTION_WRITE')") public PostProductionTaskResponse update(@PathVariable Long id,@Valid @RequestBody PostProductionTaskRequest request){return service.update(id,request);}
@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) @PreAuthorize("hasAuthority('POSTPRODUCTION_DELETE')") public void delete(@PathVariable Long id){service.delete(id);}}
